// #d73fd4 «BUG · תוויות הניווט התחתון נשברות באמצע מילה בזום 200%» — AC: «בזום 200% תוויות הלשוניות בסרגל הניווט התחתון אינן נשברות באמצע מילה».
// История: 08.11 Android активная «תפילות» → «תפילו / ת» (реджект rej_dc6620d0); 09.11 после e6eabb8 — все 5 вкладок целые,
// активные (жирные) и неактивные, 3/3 (Pixel 6, app 1.0.0 (7), wm density 840; .qa/session-2026-11-09.json). עבר QA 09.11.
// Мера: высота подписи при 200% / (высота при обычной плотности × 2) = число строк ≤ числу слов (однословные — 1 строка).
// Кейс: .qa/tests/zoom-200/Z2-03-tab-labels.md. Только просмотр. Плотность возвращается в after().
import { driver, expect } from '@wdio/globals';
import { TABS, goTab, type Tab } from '../../helpers/nav.ts';
import { goHome, type UiNode } from '../_lib/readiness-1910.ts';
import { skipWith } from '../_lib/app-0710.ts';
import { zoomOn, zoomOff, textNode, insideScreenX, overlaps, linesAtZoom, wordCount, saveShot } from '../_lib/app-0911.ts';

/** Подпись вкладки — нижние 20% экрана. */
async function tabLabel(t: Tab) {
  const { height } = await driver.getWindowSize();
  return textNode(t, (n) => n.y > height * 0.8);
}
async function allLabels() {
  const out = {} as Record<Tab, UiNode>;
  for (const t of TABS) out[t] = await tabLabel(t);
  return out;
}

describe('09.11 — зум 200% (Android): подписи нижней навигации (#d73fd4)', () => {
  before(function () { if (!driver.isAndroid) skipWith(this, 'зум через wm density — только Android'); });
  after(async () => { if (driver.isAndroid) await zoomOff(); });

  it('Z2-03 При wm density 840 «תהילים», «תפילות», «בית», «המסע שלי», «ברכות» — активная и неактивные — не рвутся внутри слова, не налезают друг на друга #d73fd4 @android @prod-safe @manual-check', async () => {
    await goHome();
    const normal = await allLabels();

    await zoomOn();
    // Каждая вкладка по очереди активная (жирная): проверяем все 5 подписей на каждом экране.
    for (const active of TABS) {
      await goTab(active);
      const z = await allLabels();
      await saveShot(`q29-active-${TABS.indexOf(active) + 1}.png`);
      for (const t of TABS) {
        const lines = linesAtZoom(z[t].h, normal[t].h);
        console.log(`[Q-29] активна «${active}»: «${t}» ${z[t].w}×${z[t].h} → ~${lines} строк`);
        expect(lines).toBeLessThanOrEqual(wordCount(t));
        expect(await insideScreenX(z[t])).toBe(true);
      }
      for (let i = 0; i < TABS.length - 1; i++) expect(overlaps(z[TABS[i]], z[TABS[i + 1]])).toBe(false);
    }
    // Глазами по скринам qa-0911/q29-active-*.png: ни одна подпись не разорвана (особо — активная «תפילות»).
  });
});
